fn process_dfs_message_command_for_test(
    local_node_id: NodeId,
    command: DfsMessageCommand,
    content: LocalContentStore,
    metadata_backend: Box<dyn DfsMetadataBackend>,
    control_plane: Option<Box<dyn DfsControlPlaneKvClient>>,
) -> Result<DfsMessageProcessResult, DfsError> {
    let message_sender: DfsMessageSender = Arc::new(|endpoint, command, _timeout| {
        Err(DfsPeerTransportError::new(format!(
            "unexpected DFS message hop to {} while processing test command {}",
            endpoint, command.request_id
        )))
    });
    let transport = DfsEndpointServedMessageTransport::new_with_message_sender(
        local_node_id,
        Vec::new(),
        message_sender,
        DEFAULT_DFS_MESSAGE_CONNECT_TIMEOUT,
    );
    let mut service = NetworkedDfsService::new(transport, content);
    if let Some(control_plane) = control_plane {
        service = service.with_boxed_control_plane(control_plane);
    }
    let mut service = service.with_boxed_metadata_backend(metadata_backend)?;
    service.process_message_command(command)
}

#[test]
fn dfs_adaptive_transfer_windows_stay_byte_bounded() {
    assert_eq!(DFS_BLOB_CHUNK_BYTES, 4 * 1024 * 1024);
    assert_eq!(DFS_BLOB_INLINE_LIMIT_BYTES, 1024 * 1024);

    let large_transfer = 128 * 1024 * 1024;
    let byte_budget_window =
        (DFS_ADAPTIVE_TRANSFER_WINDOW_MAX_BYTES / DFS_BLOB_CHUNK_BYTES as u64) as u32;
    assert_eq!(
        dfs_adaptive_chunk_window_size(
            DfsTransferProfile::Conservative,
            large_transfer,
            DFS_READ_CHUNK_WINDOW_SIZE,
        ),
        byte_budget_window
    );
    assert_eq!(
        dfs_adaptive_chunk_window_size(
            DfsTransferProfile::Lan,
            large_transfer,
            DFS_READ_CHUNK_WINDOW_SIZE,
        ),
        byte_budget_window
    );
    assert_eq!(
        dfs_adaptive_chunk_window_size(
            DfsTransferProfile::Local,
            large_transfer,
            DFS_READ_CHUNK_WINDOW_SIZE,
        ),
        byte_budget_window
    );
}

#[test]
fn content_hash_range_fallback_validates_returned_window_not_full_blob_size() {
    let root = temp_root("content_hash_range_fallback_validates_window");
    let node = NodeId::from_legacy_named("node_content_hash_range_window").expect("node");
    let object_id =
        DfsObjectId::from_legacy_named("obj_content_hash_range_window").expect("object");
    let version =
        DfsVersion::from_legacy_named("version_content_hash_range_window").expect("version");
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let dfs = NetworkedDfsService::new(ReceiveOnlyTransport::new(node), content);
    let bytes = (0..64).collect::<Vec<u8>>();
    let manifest = dfs
        .content
        .put_object_version_blob_only(object_id.as_str(), version.as_str(), &bytes)
        .expect("blob-only content");

    let mut reader = dfs
        .open_content_hash_range_stream(
            &object_id,
            &version,
            &manifest.content_hash,
            Some(bytes.len() as u64),
            16,
            bytes.len(),
        )
        .expect("range inside expected object size");
    let mut actual = Vec::new();
    reader.read_to_end(&mut actual).expect("read range");

    assert_eq!(actual, bytes[16..]);
}

#[test]
fn dfs_message_read_requests_require_fresh_metadata() {
    let source = NodeId::from_legacy_named("node_protocol_fresh_source").expect("source");
    let target = NodeId::from_legacy_named("node_protocol_fresh_target").expect("target");
    let object_id = DfsObjectId::from_legacy_named("obj_protocol_fresh").expect("object");
    let version = DfsVersion::from_legacy_named("version_protocol_fresh").expect("version");
    let read = test_dfs_message_command_from_message(
        &source,
        &target,
        1,
        DfsNetworkMessage::ReadRequest(DfsReadRequest {
            request_id: "dfs_read_fresh_metadata".to_string(),
            object_id: object_id.clone(),
            version: Some(version.clone()),
            content_hash: Some("blake3:readfresh".to_string()),
            content_size_bytes: Some(12),
            range_offset: None,
            range_max_bytes: None,
            start_chunk_index: 0,
            max_chunks: 0,
        }),
    );
    let bulk = test_dfs_message_command_from_message(
        &source,
        &target,
        2,
        DfsNetworkMessage::BulkReadRequest(DfsBulkReadRequest {
            request_id: "dfs_bulk_read_fresh_metadata".to_string(),
            reads: vec![DfsBulkReadItem {
                request_id: "dfs_bulk_read_item".to_string(),
                object_id,
                version,
                content_hash: "blake3:bulkreadfresh".to_string(),
                content_size_bytes: 12,
            }],
        }),
    );

    assert!(dfs_message_requires_fresh_metadata(&read));
    assert!(dfs_message_requires_fresh_metadata(&bulk));
}

#[test]
fn dfs_message_repair_progress_is_only_inline_for_explicit_foreground_repair_writes() {
    let source = NodeId::from_legacy_named("node_protocol_repair_source").expect("source");
    let target = NodeId::from_legacy_named("node_protocol_repair_target").expect("target");
    let file_system_id = sifs_file_system_id();
    let namespace_command = |request_id: &str, operation| {
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: request_id.to_string(),
            file_system_id: file_system_id.clone(),
            requesting_node_id: source.clone(),
            include_metadata_journal_batches: false,
            metadata_journal_after_sequences: Vec::new(),
            operation,
        })
    };
    let lookup = test_dfs_message_command_from_message(
        &source,
        &target,
        1,
        namespace_command(
            "dfs_lookup_no_inline_repair",
            DfsNamespaceOperation::LookupPath {
                path: "/services/no-inline-repair".to_string(),
            },
        ),
    );
    let mkdir = test_dfs_message_command_from_message(
        &source,
        &target,
        2,
        namespace_command(
            "dfs_mkdir_no_inline_repair",
            DfsNamespaceOperation::MkdirAll {
                path: "/services/no-inline-repair".to_string(),
            },
        ),
    );
    let read = test_dfs_message_command_from_message(
        &source,
        &target,
        3,
        DfsNetworkMessage::ReadRequest(DfsReadRequest {
            request_id: "dfs_read_no_inline_repair".to_string(),
            object_id: DfsObjectId::from_legacy_named("obj_no_inline_repair").expect("object"),
            version: None,
            content_hash: Some("blake3:noinline".to_string()),
            content_size_bytes: Some(0),
            range_offset: None,
            range_max_bytes: None,
            start_chunk_index: 0,
            max_chunks: 0,
        }),
    );
    let object_id = DfsObjectId::from_legacy_named("obj_foreground_repair_write").expect("object");
    let mut background_write =
        test_routed_write_command("dfs_background_write_no_inline_repair", &source, &object_id);
    background_write.foreground_replica_repair = false;
    let background_write = test_dfs_message_command_from_message(
        &source,
        &target,
        4,
        DfsNetworkMessage::DistributedWriteRequest(background_write),
    );
    let foreground_repair_write = test_dfs_message_command_from_message(
        &source,
        &target,
        5,
        DfsNetworkMessage::DistributedWriteRequest(test_routed_write_command(
            "dfs_foreground_repair_write",
            &source,
            &object_id,
        )),
    );

    assert!(!dfs_message_allows_write_repair_progress(&lookup));
    assert!(!dfs_message_allows_write_repair_progress(&mkdir));
    assert!(!dfs_message_allows_write_repair_progress(&read));
    assert!(!dfs_message_allows_write_repair_progress(&background_write));
    assert!(dfs_message_allows_write_repair_progress(
        &foreground_repair_write
    ));
}

fn object_field<'a>(value: &'a Value, key: &str) -> &'a Value {
    let Value::Object(object) = value else {
        panic!("expected object value for field {key}, got {value:?}");
    };
    object
        .fields
        .iter()
        .find(|field| field.key == key)
        .map(|field| &field.value)
        .unwrap_or_else(|| panic!("missing object field {key} in {object:?}"))
}

fn assert_native_bytes_field(value: &impl serde::Serialize, key: &str) {
    let value = sinomo_object::serde_ext::to_value(value).expect("serialize value");
    let field = object_field(&value, key);
    assert!(
        matches!(field, Value::Bytes(_)),
        "expected {key} to serialize as native bytes, got {field:?}"
    );
}

fn dfs_message_trace_label(message: &DfsNetworkMessage) -> String {
    match message {
        DfsNetworkMessage::ReadRequest(_) => "read-request".to_string(),
        DfsNetworkMessage::ReadResponse(_) => "read-response".to_string(),
        DfsNetworkMessage::ReadResponseChunk(chunk) => format!(
            "read-response-chunk:{}/{}:{}b",
            chunk.chunk_index.saturating_add(1),
            chunk.total_chunks,
            chunk.bytes.len()
        ),
        DfsNetworkMessage::BulkReadRequest(_) => "bulk-read-request".to_string(),
        DfsNetworkMessage::BulkReadResponse(_) => "bulk-read-response".to_string(),
        DfsNetworkMessage::WriteRequest(_) => "write-request".to_string(),
        DfsNetworkMessage::WriteResponse(_) => "write-response".to_string(),
        DfsNetworkMessage::DistributedWriteRequest(command) => {
            format!("distributed-write-request:{}", command.request_id)
        }
        DfsNetworkMessage::DistributedWriteResponse(response) => {
            format!("distributed-write-response:{}", response.request_id)
        }
        DfsNetworkMessage::NamespaceRequest(_) => "namespace-request".to_string(),
        DfsNetworkMessage::NamespaceResponse(_) => "namespace-response".to_string(),
        DfsNetworkMessage::FetchBlob(command) => {
            format!("fetch-blob:{}", command.intent_id)
        }
        DfsNetworkMessage::FetchBlobResponse(response) => {
            format!("fetch-blob-response:{}", response.intent_id)
        }
        DfsNetworkMessage::FetchBlobResponseChunk(chunk) => format!(
            "fetch-blob-response-chunk:{}:{}/{}:{}b",
            chunk.intent_id,
            chunk.chunk_index.saturating_add(1),
            chunk.total_chunks,
            chunk.bytes.len()
        ),
        DfsNetworkMessage::StageBlob(stage) => {
            format!("stage-blob:{}", stage.intent_id)
        }
        DfsNetworkMessage::StageBlobChunk(chunk) => format!(
            "stage-blob-chunk:{}:{}/{}:{}b",
            chunk.intent_id,
            chunk.chunk_index.saturating_add(1),
            chunk.total_chunks,
            chunk.bytes.len()
        ),
        DfsNetworkMessage::StageBlobResponse(response) => {
            format!("stage-blob-response:{}", response.intent_id)
        }
        DfsNetworkMessage::StagePatch(_) => "stage-patch".to_string(),
        DfsNetworkMessage::StagePatchChunk(chunk) => format!(
            "stage-patch-chunk:{}/{}:{}b",
            chunk.chunk_index.saturating_add(1),
            chunk.total_chunks,
            chunk.bytes.len()
        ),
        DfsNetworkMessage::CommitVersion(_) => "commit-version".to_string(),
        DfsNetworkMessage::CommitVersionResponse(_) => "commit-version-response".to_string(),
        DfsNetworkMessage::RepairReplica(_) => "repair-replica".to_string(),
        DfsNetworkMessage::RepairReplicaChunk(chunk) => format!(
            "repair-replica-chunk:{}/{}:{}b",
            chunk.chunk_index.saturating_add(1),
            chunk.total_chunks,
            chunk.bytes.len()
        ),
        DfsNetworkMessage::RepairReplicaResponse(_) => "repair-replica-response".to_string(),
        DfsNetworkMessage::MetadataJournalBatch(_) => "metadata-journal-batch".to_string(),
        DfsNetworkMessage::MetadataJournalBatchResponse(_) => {
            "metadata-journal-batch-response".to_string()
        }
        DfsNetworkMessage::MetadataSnapshotInstall(_) => "metadata-snapshot-install".to_string(),
        DfsNetworkMessage::MetadataSnapshotInstallResponse(_) => {
            "metadata-snapshot-install-response".to_string()
        }
    }
}

fn networked_dfs_event_trace_label(event: &NetworkedDfsServiceEvent) -> String {
    match event {
        NetworkedDfsServiceEvent::BlobFetched {
            intent_id,
            source_node_id,
            ..
        } => format!("blob-fetched:{intent_id}:from:{source_node_id}"),
        NetworkedDfsServiceEvent::BlobFetchRejected {
            intent_id,
            source_node_id,
            reason,
            ..
        } => format!("blob-fetch-rejected:{intent_id}:from:{source_node_id}:{reason}"),
        NetworkedDfsServiceEvent::BlobStaged {
            intent_id,
            replica_node_id,
            ..
        } => format!("blob-staged:{intent_id}:to:{replica_node_id}"),
        NetworkedDfsServiceEvent::BlobStageRejected {
            intent_id,
            replica_node_id,
            reason,
            ..
        } => format!("blob-stage-rejected:{intent_id}:to:{replica_node_id}:{reason}"),
        NetworkedDfsServiceEvent::RemoteWriteServed {
            request_id, result, ..
        } => format!("remote-write-served:{request_id}:{result:?}"),
        NetworkedDfsServiceEvent::RemoteWriteCompleted {
            request_id, result, ..
        } => format!("remote-write-completed:{request_id}:{result:?}"),
        _ => "event".to_string(),
    }
}

fn protocol_test_bytes() -> Vec<u8> {
    vec![0, 1, 2, 3, 253, 254, 255]
}

fn protocol_test_write_request() -> DfsWriteRequest {
    DfsWriteRequest {
        file_system_id: sinomo_core::Id::from_legacy_named("fs").expect("fs id"),
        object_id: sinomo_core::Id::from_legacy_named("object").expect("object id"),
        target_version: sinomo_core::Id::from_legacy_named("version").expect("version id"),
        requesting_node_id: sinomo_core::Id::from_legacy_named("node").expect("node id"),
    }
}

#[test]
fn dfs_protocol_binary_payloads_use_native_bytes_codec() {
    let object_id = DfsObjectId::from_legacy_named("object").expect("object id");
    let version = DfsVersion::from_legacy_named("version").expect("version id");
    let node_id = NodeId::from_legacy_named("node").expect("node id");
    let file_system_id = DfsFileSystemId::from_legacy_named(SIFS_FILE_SYSTEM_ID).expect("fs id");
    let bytes = protocol_test_bytes();

    assert_native_bytes_field(
        &DfsReadData {
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some("hash".to_string()),
            bytes: bytes.clone(),
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsReadRangeData {
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some("hash".to_string()),
            offset: 0,
            total_size_bytes: bytes.len() as u64,
            bytes: bytes.clone(),
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsReadResponseChunk {
            request_id: "read".to_string(),
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some("hash".to_string()),
            range_offset: None,
            object_total_size_bytes: None,
            total_size_bytes: bytes.len() as u64,
            chunk_index: 0,
            total_chunks: 1,
            chunk_hash: None,
            bytes: bytes.clone(),
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsWriteCommand {
            request_id: "write".to_string(),
            request: protocol_test_write_request(),
            bytes: bytes.clone(),
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsDistributedWriteCommand {
            request_id: "distributed-write".to_string(),
            request: protocol_test_write_request(),
            expected_base_version: None,
            metadata_journal_after_sequence: None,
            bytes: bytes.clone(),
            content_hash: Some("hash".to_string()),
            content_size_bytes: Some(bytes.len() as u64),
            desired_replica_nodes: vec![node_id.clone()],
            policy: DfsReplicationPolicy::new(1, 1).expect("policy"),
            object_metadata: None,
            touch_parent_on_create: true,
            foreground_replica_repair: true,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsStageBlobCommand {
            request_id: "stage".to_string(),
            intent_id: "intent".to_string(),
            file_system_id: file_system_id.clone(),
            object_id: object_id.clone(),
            expected_base_version: None,
            version: version.clone(),
            content_hash: "hash".to_string(),
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsStageBlobChunkCommand {
            request_id: "stage-chunk".to_string(),
            intent_id: "intent".to_string(),
            file_system_id: file_system_id.clone(),
            object_id: object_id.clone(),
            expected_base_version: None,
            version: version.clone(),
            content_hash: "hash".to_string(),
            total_size_bytes: bytes.len() as u64,
            chunk_index: 0,
            total_chunks: 1,
            chunk_hash: None,
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsStagePatchCommand {
            request_id: "stage-patch".to_string(),
            intent_id: "intent".to_string(),
            file_system_id: file_system_id.clone(),
            object_id: object_id.clone(),
            base_version: version.clone(),
            version: version.clone(),
            content_hash: "hash".to_string(),
            offset: 0,
            patch_hash: "patch".to_string(),
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsStagePatchChunkCommand {
            request_id: "stage-patch-chunk".to_string(),
            intent_id: "intent".to_string(),
            file_system_id: file_system_id.clone(),
            object_id: object_id.clone(),
            base_version: version.clone(),
            version: version.clone(),
            content_hash: "hash".to_string(),
            offset: 0,
            patch_hash: "patch".to_string(),
            total_size_bytes: bytes.len() as u64,
            chunk_index: 0,
            total_chunks: 1,
            chunk_hash: None,
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsRepairReplicaCommand {
            request_id: "repair".to_string(),
            intent_id: "intent".to_string(),
            file_system_id: file_system_id.clone(),
            object_id: object_id.clone(),
            expected_base_version: None,
            version: version.clone(),
            content_hash: "hash".to_string(),
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsRepairReplicaChunkCommand {
            request_id: "repair-chunk".to_string(),
            intent_id: "intent".to_string(),
            file_system_id,
            object_id: object_id.clone(),
            expected_base_version: None,
            version: version.clone(),
            content_hash: "hash".to_string(),
            total_size_bytes: bytes.len() as u64,
            chunk_index: 0,
            total_chunks: 1,
            chunk_hash: None,
            bytes: bytes.clone(),
            object_metadata: None,
        },
        "bytes",
    );
    assert_native_bytes_field(
        &DfsFetchBlobResponseChunk {
            request_id: "fetch-chunk".to_string(),
            intent_id: "intent".to_string(),
            object_id: object_id.clone(),
            version,
            source_node_id: node_id,
            content_hash: "hash".to_string(),
            total_size_bytes: bytes.len() as u64,
            chunk_index: 0,
            total_chunks: 1,
            chunk_hash: None,
            bytes: bytes.clone(),
        },
        "bytes",
    );

    let found = sinomo_object::serde_ext::to_value(&DfsFetchBlobResult::Found {
        content_hash: "hash".to_string(),
        bytes,
    })
    .expect("serialize fetch result");
    assert!(
        matches!(
            object_field(object_field(&found, "found"), "bytes"),
            Value::Bytes(_)
        ),
        "expected DfsFetchBlobResult::Found bytes to serialize as native bytes"
    );
}

#[test]
fn dfs_message_classifier_keeps_lookup_connectivity_observing() {
    let local = NodeId::from_legacy_named("node_read_classifier_local").expect("local");
    let remote = NodeId::from_legacy_named("node_read_classifier_remote").expect("remote");
    let file_system_id = sifs_file_system_id();
    let read = test_dfs_message_command_from_message(
        &local,
        &remote,
        1,
        DfsNetworkMessage::ReadRequest(DfsReadRequest {
            request_id: "read-request".to_string(),
            object_id: DfsObjectId::from_legacy_named("read_object").expect("object id"),
            version: None,
            content_hash: None,
            content_size_bytes: None,
            range_offset: None,
            range_max_bytes: None,
            start_chunk_index: 0,
            max_chunks: 0,
        }),
    );
    assert!(dfs_message_is_read_only_request(&read));
    assert!(dfs_message_requires_fresh_metadata(&read));

    let lookup = test_dfs_message_command_from_message(
        &local,
        &remote,
        2,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "lookup-request".to_string(),
            file_system_id: file_system_id.clone(),
            requesting_node_id: local.clone(),
            include_metadata_journal_batches: true,
            metadata_journal_after_sequences: Vec::new(),
            operation: DfsNamespaceOperation::LookupPath {
                path: "/services/example.txt".to_string(),
            },
        }),
    );
    assert!(!dfs_message_is_read_only_request(&lookup));
    assert!(
        dfs_message_requires_fresh_metadata(&lookup),
        "lookup requests still require fresh daemon metadata before answering primary path checks"
    );

    let lookup_paths = test_dfs_message_command_from_message(
        &local,
        &remote,
        4,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "lookup-paths-request".to_string(),
            file_system_id: file_system_id.clone(),
            requesting_node_id: local.clone(),
            include_metadata_journal_batches: true,
            metadata_journal_after_sequences: Vec::new(),
            operation: DfsNamespaceOperation::LookupPaths {
                paths: vec![
                    "/services/example-a.txt".to_string(),
                    "/services/example-b.txt".to_string(),
                ],
            },
        }),
    );
    assert!(!dfs_message_is_read_only_request(&lookup_paths));
    assert!(
        dfs_message_requires_fresh_metadata(&lookup_paths),
        "batched lookup requests still require fresh daemon metadata before answering primary path checks"
    );

    let sync = test_dfs_message_command_from_message(
        &local,
        &remote,
        3,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "sync-request".to_string(),
            file_system_id: file_system_id.clone(),
            requesting_node_id: local.clone(),
            include_metadata_journal_batches: true,
            metadata_journal_after_sequences: Vec::new(),
            operation: DfsNamespaceOperation::SyncPath {
                path: "/services/example.txt".to_string(),
            },
        }),
    );
    assert!(!dfs_message_is_read_only_request(&sync));
    assert!(dfs_message_requires_fresh_metadata(&sync));

    let apply = test_dfs_message_command_from_message(
        &local,
        &remote,
        5,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "apply-request".to_string(),
            file_system_id: file_system_id.clone(),
            requesting_node_id: local.clone(),
            include_metadata_journal_batches: true,
            metadata_journal_after_sequences: Vec::new(),
            operation: DfsNamespaceOperation::ApplyTransaction {
                transaction: DfsNamespaceTransaction {
                    transaction_id: "bulk-transaction".to_string(),
                    file_system_id,
                    objects: Vec::new(),
                    versions: Vec::new(),
                    created_at: OffsetDateTime::UNIX_EPOCH,
                },
            },
        }),
    );
    assert!(!dfs_message_is_read_only_request(&apply));
    assert!(dfs_message_requires_fresh_metadata(&apply));
}

