#[test]
fn async_dfs_message_transport_in_process_sends_waits_and_drains() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    runtime.block_on(async {
        let network = AsyncInProcessNetwork::new();
        let node_a = NodeId::from_legacy_named("node_dfs_async_frame_a").expect("node a");
        let node_b = NodeId::from_legacy_named("node_dfs_async_frame_b").expect("node b");
        let mut transport_a = network.add_node(node_a.clone());
        let mut transport_b = network.add_node(node_b.clone());
        let message =
            test_dfs_lookup_routed_message(&node_a, &node_b, 7, "/async/message-transport");

        AsyncDfsMessageTransport::send_routed_message_async(&mut transport_a, &node_b, message)
            .await
            .expect("send");
        assert!(
            AsyncDfsMessageTransport::wait_for_incoming_async(&mut transport_b, Duration::ZERO)
                .await
                .expect("wait")
        );
        let inbound = AsyncDfsMessageTransport::drain_incoming_messages_async(&mut transport_b)
            .await
            .expect("drain");

        assert_eq!(inbound.len(), 1);
        assert_eq!(inbound[0].target_node_id, node_b);
        assert_eq!(inbound[0].source_node_id, node_a);
        assert_eq!(inbound[0].frame_id, 7);
    });
}

#[derive(Clone, Debug)]
struct ClusterPathDfsControlPlaneKvClient {
    cluster_paths: ClusterPaths,
}

impl ClusterPathDfsControlPlaneKvClient {
    fn new(cluster_paths: &ClusterPaths) -> Self {
        Self {
            cluster_paths: cluster_paths.clone(),
        }
    }

    fn kv_error(&self, source: impl std::fmt::Display) -> sinomo_kv::KvError {
        sinomo_kv::KvError::Io {
            path: self.cluster_paths.kv_snapshot.display().to_string(),
            detail: source.to_string(),
        }
    }
}

fn append_cluster_kv_command(
    paths: &ClusterPaths,
    node_id: &NodeId,
    command: sinomo_kv::KvCommand,
) -> Result<sinomo_kv::KvSnapshot, sinomo_network::NetworkError> {
    paths
        .kv_paths()
        .append_kv_command_and_publish(
            node_id,
            command,
            sinomo_kv::cluster_kv_key_can_defer_materialized_snapshot,
        )
        .map_err(Into::into)
}

fn append_cluster_kv_command_with_response(
    paths: &ClusterPaths,
    node_id: &NodeId,
    command: sinomo_kv::KvCommand,
) -> Result<(sinomo_kv::KvSnapshot, Option<sinomo_kv::KvTxnResponse>), sinomo_network::NetworkError>
{
    paths
        .kv_paths()
        .append_kv_command_with_response_and_publish(
            node_id,
            command,
            sinomo_kv::cluster_kv_key_can_defer_materialized_snapshot,
        )
        .map_err(Into::into)
}

impl DfsControlPlaneKvClient for ClusterPathDfsControlPlaneKvClient {
    fn get(&self, key: &str) -> Result<Option<sinomo_kv::KvEntry>, sinomo_kv::KvError> {
        sinomo_kv::read_cluster_kv_entry(&self.cluster_paths.kv_paths(), key)
    }

    fn range_prefix(&self, prefix: &str) -> Result<Vec<sinomo_kv::KvEntry>, sinomo_kv::KvError> {
        sinomo_kv::read_cluster_kv_prefix_entries(&self.cluster_paths.kv_paths(), prefix)
    }

    fn put(
        &mut self,
        key: String,
        value: Vec<u8>,
    ) -> Result<sinomo_kv::KvRevision, sinomo_kv::KvError> {
        let response = self.txn(sinomo_kv::KvTxn {
            compares: Vec::new(),
            success: vec![sinomo_kv::KvOp::Put {
                key,
                value,
                lease_id: None,
            }],
            failure: Vec::new(),
        })?;
        Ok(response.revision)
    }

    fn txn(
        &mut self,
        txn: sinomo_kv::KvTxn,
    ) -> Result<sinomo_kv::KvTxnResponse, sinomo_kv::KvError> {
        let state = sinomo_network::read_cluster_state(&self.cluster_paths)
            .map_err(|source| self.kv_error(source))?;
        let (snapshot, response) = append_cluster_kv_command_with_response(
            &self.cluster_paths,
            &state.local_node_id,
            sinomo_kv::KvCommand::Txn(txn),
        )
        .map_err(|source| self.kv_error(source))?;
        Ok(response.unwrap_or(sinomo_kv::KvTxnResponse {
            succeeded: true,
            revision: snapshot.revision,
            responses: Vec::new(),
        }))
    }
}

#[derive(Debug)]
struct CountingDfsControlPlaneKvClient {
    inner: InProcessKvStore,
    range_prefix_calls: Arc<AtomicUsize>,
}

impl CountingDfsControlPlaneKvClient {
    fn new(inner: InProcessKvStore, range_prefix_calls: Arc<AtomicUsize>) -> Self {
        Self {
            inner,
            range_prefix_calls,
        }
    }
}

impl DfsControlPlaneKvClient for CountingDfsControlPlaneKvClient {
    fn get(&self, key: &str) -> Result<Option<sinomo_kv::KvEntry>, sinomo_kv::KvError> {
        DfsControlPlaneKvClient::get(&self.inner, key)
    }

    fn range_prefix(&self, prefix: &str) -> Result<Vec<sinomo_kv::KvEntry>, sinomo_kv::KvError> {
        self.range_prefix_calls.fetch_add(1, Ordering::SeqCst);
        DfsControlPlaneKvClient::range_prefix(&self.inner, prefix)
    }

    fn put(
        &mut self,
        key: String,
        value: Vec<u8>,
    ) -> Result<sinomo_kv::KvRevision, sinomo_kv::KvError> {
        DfsControlPlaneKvClient::put(&mut self.inner, key, value)
    }

    fn txn(
        &mut self,
        txn: sinomo_kv::KvTxn,
    ) -> Result<sinomo_kv::KvTxnResponse, sinomo_kv::KvError> {
        DfsControlPlaneKvClient::txn(&mut self.inner, txn)
    }
}

